                if len(qs) >= total_q_needed:
                    break
                curr_idx = start_id + len(qs)
                qid = f"GK{curr_idx:05d}"
                
                # If cycle > 0, generate related historical fact queries
                cycle = len(qs) // len(base_items)
                if cycle == 0:
                    q_text = q_hi
                    exp_text = exp
                    options = list(opts)
                    correct = ans
                    difficulty = diff
                else:
                    difficulty = diff_cycle[len(qs) % len(diff_cycle)]
                    # Create variation
